WITH valid AS (SELECT id, session_id, event_type, page, event_time, duration_sec, LENGTH(event_type) AS event_type_length FROM web_events WHERE page IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM valid), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT island_id, CASE WHEN event_type_length >= 65 THEN 'LARGE' ELSE 'SMALL' END AS event_type_length_tier, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, MAX(island_id) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_max_island_id, ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN page = '/cart' THEN 1 END), 0), 2) AS session_start_flag_per_cart, RANK() OVER (PARTITION BY island_id ORDER BY ROUND(SUM(session_start_flag) / NULLIF(COUNT(CASE WHEN page = '/cart' THEN 1 END), 0), 2) DESC) AS session_start_flag_per_cart_rank FROM sessionized GROUP BY island_id, event_type_length_tier ORDER BY event_type_length_tier DESC;
